type StopOptions = Partial<GuideStop> & {
  sourcePhoto: string;
  officialUrl: string;
  editorialUrls?: string[];
  mapQuery?: string;
};

function stop(id: string, name: string, coordinates: [number, number], description: string, options: StopOptions): GuideStop {
  const { sourcePhoto, officialUrl, editorialUrls = [], mapQuery, bookingUrl, sourceEvidence, imageSourceUrl, sourceUrls = [], ...rest } = options;
  const mapUrl = sourceEvidence?.mapUrl ?? maps(mapQuery ?? `${name} Hamburg`);
  const imageUrl = imageSourceUrl ?? sourcePhoto;
  const evidence = [officialUrl, mapUrl, imageUrl, ...editorialUrls, ...sourceUrls].filter(Boolean);
  return {
    id, name, coordinates, description, photo: sourcePhoto, imageSourceUrl: imageUrl,
    sourceUrls: [...new Set(evidence)],
    sourceEvidence: {
      officialUrl, mapUrl, currentStatusUrl: mapUrl, imageSourceUrl: imageUrl, editorialUrls,
      checkedAt, notes: "Candidate retained after official-page, map-status, hours, and media review on the listed check date.",
      ...sourceEvidence,
    },
    officialUrl,
    ...(bookingUrl ? { bookingUrl } : {}),
    ...rest,
  };
}

