function sourcesFor(label: string, overviewUrl: string, stops: GuideStop[]): ListSource[] {
  return [source(`${label} planning overview`, overviewUrl), ...stops.map((item) => source(`${item.name} official/property source`, item.officialUrl!))];
}

const guideSources = {
  dining: sourcesFor("Hamburg dining", "https://www.hamburg-travel.com/shopping-enjoying/restaurants-cafes/", diningStops),
  cheapEats: sourcesFor("Hamburg affordable food", "https://www.hamburg-travel.com/shopping-enjoying/restaurants-cafes/", cheapEatStops),
  hotels: sourcesFor("Hamburg hotels", "https://www.hamburg-travel.com/booking/hotels/", hotelStops),
  hostels: sourcesFor("Hamburg hostels", "https://www.hostelworld.com/hostels/europe/germany/hamburg/", hostelStops),
  pubs: sourcesFor("Hamburg casual nightlife", "https://www.hamburg-travel.com/shopping-enjoying/nightlife/", pubStops),
  cocktails: sourcesFor("Hamburg cocktail bars", "https://www.hamburg-travel.com/shopping-enjoying/nightlife/", cocktailStops),
  culture: sourcesFor("Hamburg culture", "https://www.hamburg-travel.com/see-explore/culture-music/", cultureStops),
  activities: sourcesFor("Hamburg attractions", "https://www.hamburg-travel.com/see-explore/sightseeing/", activityStops),
};

function guide(category: ListCategory, id: string, slug: string, seoSlug: string, title: string, description: string, stops: GuideStop[], sources: ListSource[], seoTitle: string, seoDescription: string): MapList {
  return {
    id, slug, seoSlug, seoTitle, seoDescription, title, description,
    photo: stops[0]?.photo,
    url: maps(`${title} Hamburg`),
    category,
    location: hamburgLocation,
    creator: { id: `user-rguide-${category.toLowerCase()}`, name: `R ${category}`, avatar: avatar(category) },
    upvotes: 0,
    createdAt,
    stops,
    sources,
  };
}

